local BombardMaker = {}
local PRODUCTS = {
    light_bombard = { name = "Lahka bombarda", ironCost = 5, woodCost = 3, gunpowderCost = 2, time = 7, cost = 400, attack = 65, range = 220, durability = 40, description = "Lahka bombarda za obleganje." },
    bronze_bombard = { name = "Bronasta bombarda", bronzeCost = 6, ironCost = 3, woodCost = 4, gunpowderCost = 3, time = 11, cost = 1000, attack = 100, range = 270, durability = 60, prestige = 4, description = "Bronasta bombarda z veliko močjo." },
    iron_bombard = { name = "Železna bombarda", ironCost = 9, woodCost = 5, gunpowderCost = 4, time = 15, cost = 2200, attack = 150, range = 320, durability = 80, prestige = 8, happiness = 1, description = "Železna bombarda za težke oblege." },
    heavy_bombard = { name = "Težka bombarda", ironCost = 12, bronzeCost = 5, woodCost = 6, gunpowderCost = 5, time = 19, cost = 4400, attack = 220, range = 380, durability = 100, prestige = 15, happiness = 2, description = "Težka bombarda za najmočnejše zidove." },
    silver_decorated_bombard = { name = "Srebrno okrašena bombarda", ironCost = 12, bronzeCost = 5, silverCost = 2, woodCost = 6, gunpowderCost = 5, time = 23, cost = 8200, attack = 290, range = 440, durability = 120, prestige = 26, happiness = 4, description = "Bombarda s srebrnim okrasjem za kraljevo vojsko." },
    royal_grand_bombard = { name = "Kraljevski velika bombarda", ironCost = 16, bronzeCost = 10, steelCost = 5, goldCost = 3, silverCost = 2, woodCost = 9, gunpowderCost = 7, jewelCost = 1, time = 30, cost = 16000, attack = 410, range = 540, durability = 175, prestige = 68, happiness = 14, description = "Velika kraljevska bombarda z zlatim in draguljnim okovjem za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Bombardarska delavnica", cost = { gold = 600, wood = 220, stone = 280 }, upkeep = 14, qualityBonus = 5 },
    foundry = { name = "Livarna bombard", cost = { gold = 2400, wood = 380, stone = 650, iron = 14, bronze = 10 }, upkeep = 55, qualityBonus = 18 },
    boring_room = { name = "Vrtalnica", cost = { gold = 5500, wood = 500, stone = 950, silver = 60, steel = 10 }, upkeep = 110, qualityBonus = 30 },
    royal_bombard_atelier = { name = "Kraljevski atelje bombard", cost = { gold = 22000, wood = 1200, stone = 2000, gold = 300, jewel = 30 }, upkeep = 420, qualityBonus = 55, prestigeBonus = 60 },
}
BombardMaker.ironStock = 14; BombardMaker.bronzeStock = 14; BombardMaker.steelStock = 10; BombardMaker.woodStock = 16; BombardMaker.silverStock = 8; BombardMaker.goldStock = 6; BombardMaker.jewelStock = 6; BombardMaker.gunpowderStock = 12
BombardMaker.productStock = {}; BombardMaker.buildings = {}; BombardMaker.maker = nil; BombardMaker.activeMaking = {}; BombardMaker.totalProducts = 0; BombardMaker.dayTimer = 0
function BombardMaker.init() BombardMaker.ironStock=14; BombardMaker.bronzeStock=14; BombardMaker.steelStock=10; BombardMaker.woodStock=16; BombardMaker.silverStock=8; BombardMaker.goldStock=6; BombardMaker.jewelStock=6; BombardMaker.gunpowderStock=12; BombardMaker.productStock={}; BombardMaker.buildings={}; BombardMaker.maker=nil; BombardMaker.activeMaking={}; BombardMaker.totalProducts=0; BombardMaker.dayTimer=0; print("[BombardMaker] Royal Bombard Maker System initialized (6 products, 4 buildings)") end
function BombardMaker.hireMaker(n,s) s=s or math.random(55,95); local c=780+s*15; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BombardMaker.maker={name=n or ("Bombardar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Bombardar najet: %s (spretnost: %d)",BombardMaker.maker.name,s),"success") end; return true end
function BombardMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BombardMaker.build(id) local ok,e=BombardMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BombardMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BombardMaker.getQualityBonus() local b=0; for _,bd in ipairs(BombardMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BombardMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BombardMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BombardMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.steelCost and BombardMaker.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.woodCost and BombardMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.silverCost and BombardMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BombardMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BombardMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.gunpowderCost and BombardMaker.gunpowderStock<(d.gunpowderCost or 0) then return false,"Premalo smodnika" end; if #BombardMaker.buildings==0 then return false,"Potrebna delavnica" end; if not BombardMaker.maker then return false,"Potreben bombardar" end; return true end
function BombardMaker.make(pt,qty) qty=qty or 1; local ok,e=BombardMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BombardMaker.ironStock=BombardMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BombardMaker.bronzeStock=BombardMaker.bronzeStock-d.bronzeCost*qty end; if d.steelCost then BombardMaker.steelStock=BombardMaker.steelStock-d.steelCost*qty end; if d.woodCost then BombardMaker.woodStock=BombardMaker.woodStock-d.woodCost*qty end; if d.silverCost then BombardMaker.silverStock=BombardMaker.silverStock-d.silverCost*qty end; if d.goldCost then BombardMaker.goldStock=BombardMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BombardMaker.jewelStock=BombardMaker.jewelStock-d.jewelCost*qty end; if d.gunpowderCost then BombardMaker.gunpowderStock=BombardMaker.gunpowderStock-d.gunpowderCost*qty end; local t=d.time; if BombardMaker.maker then t=math.max(1,t-math.floor(BombardMaker.maker.skill/12)) end; table.insert(BombardMaker.activeMaking,{id="bombard_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,attack=d.attack or 0,range=d.range or 0,durability=d.durability or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BombardMaker.completeMaking(m) local q=1.0+(BombardMaker.getQualityBonus()/100); if BombardMaker.maker then q=q+(BombardMaker.maker.skill/150) end; q=math.min(2.5,q); BombardMaker.productStock[m.productType]=(BombardMaker.productStock[m.productType] or 0)+m.quantity; BombardMaker.totalProducts=BombardMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BombardMaker.maker then BombardMaker.maker.itemsMade=BombardMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BombardMaker.maker.skill=math.min(100,BombardMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Bombarda izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bombard.completed",{productName=m.productName,attack=m.attack,range=m.range,durability=m.durability}) end end
function BombardMaker.update(dt) if not _G.state then return end; BombardMaker.dayTimer=BombardMaker.dayTimer+dt; if BombardMaker.dayTimer>=30 then BombardMaker.dayTimer=0; for i=#BombardMaker.activeMaking,1,-1 do local m=BombardMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BombardMaker.completeMaking(m); table.remove(BombardMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BombardMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BombardMaker.maker then tu=tu+26 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BombardMaker.getStats() return {ironStock=BombardMaker.ironStock,bronzeStock=BombardMaker.bronzeStock,steelStock=BombardMaker.steelStock,woodStock=BombardMaker.woodStock,silverStock=BombardMaker.silverStock,goldStock=BombardMaker.goldStock,jewelStock=BombardMaker.jewelStock,gunpowderStock=BombardMaker.gunpowderStock,productStock=BombardMaker.productStock,numBuildings=#BombardMaker.buildings,hasMaker=BombardMaker.maker~=nil,makerName=BombardMaker.maker and BombardMaker.maker.name or "—",makerSkill=BombardMaker.maker and BombardMaker.maker.skill or 0,activeMaking=#BombardMaker.activeMaking,totalProducts=BombardMaker.totalProducts} end
return BombardMaker
